from itertools import product
from collections import defaultdict

golfers = 50
weeks = 6

def get_group(golfer, week, schedule):
    return schedule[week * golfers + golfer]

# Generate all possible schedules
schedules = list(product(range(10), repeat=weeks * golfers))

for schedule in schedules:
    # Check if the schedule is valid
    valid = True
    pairs = defaultdict(int)
    for week in range(weeks):
        for golfer1 in range(golfers):
            for golfer2 in range(golfers):
                if golfer1 < golfer2:
                    group1 = get_group(golfer1, week, schedule)
                    group2 = get_group(golfer2, week, schedule)
                    if group1 == group2:
                        pairs[(golfer1, golfer2)] += 1
                        if pairs[(golfer1, golfer2)] > 1:
                            valid = False
                            break
            if not valid:
                break
        if not valid:
            break

    # If the schedule is valid, print it and break
    if valid:
        print(schedule)
        break
else:
    print("UNSATISFIABLE")
